const variantBuckets = `-- name: VariantBuckets :many
SELECT bucket FROM asset_variants WHERE asset_id=? ORDER BY bucket
`

func (q *Queries) VariantBuckets(ctx context.Context, assetID string) ([]int, error) {
	rows, err := q.db.QueryContext(ctx, variantBuckets, assetID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int{}
	for rows.Next() {
		var bucket int
		if err := rows.Scan(&bucket); err != nil {
			return nil, err
		}
		items = append(items, bucket)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

